-- D1 schema for the vaultwarden Cloudflare Workers port.
--
-- Section 1 mirrors vaultwarden's SQLite schema EXACTLY (tables, columns, types, constraints),
-- generated by applying ../migrations/sqlite/*/up.sql in order, up to and including
-- 2026-10-10-120000_add_custom_role_permissions. Do not edit it by hand: regenerate it and
-- keep tests/schema_check.sh passing, so a vaultwarden db.sqlite3 can be copied table-by-table.
-- Stored formats: BOOLEAN = 0/1; password hashes/salts = raw BLOB (as vaultwarden).
-- Deviation: DATETIME values are stored as ISO-8601 UTC 'YYYY-MM-DDTHH:MM:SS.sssZ' (what the API
-- returns), not diesel's 'YYYY-MM-DD HH:MM:SS.ffffff'; an importer from vaultwarden must convert
-- them with strftime('%Y-%m-%dT%H:%M:%fZ', col).
--
-- Section 2 holds Workers-only tables (no vaultwarden equivalent) and extra indexes.
-- Note: D1 enforces foreign keys and section 1 has no ON DELETE CASCADE, so deletes must remove
-- child rows first (same order vaultwarden's models use).

-- ===================== Section 1: vaultwarden schema =====================
CREATE TABLE users (
  uuid                TEXT     NOT NULL PRIMARY KEY,
  created_at          DATETIME NOT NULL,
  updated_at          DATETIME NOT NULL,
  email               TEXT     NOT NULL UNIQUE,
  name                TEXT     NOT NULL,
  password_hash       BLOB     NOT NULL,
  salt                BLOB     NOT NULL,
  password_iterations INTEGER  NOT NULL,
  password_hint       TEXT,
  akey                 TEXT     NOT NULL,
  private_key         TEXT,
  public_key          TEXT,
  totp_secret         TEXT,
  totp_recover        TEXT,
  security_stamp      TEXT     NOT NULL,
  equivalent_domains  TEXT     NOT NULL,
  excluded_globals    TEXT     NOT NULL
, client_kdf_type INTEGER NOT NULL DEFAULT 0, client_kdf_iter INTEGER NOT NULL DEFAULT 100000, verified_at DATETIME DEFAULT NULL, last_verifying_at DATETIME DEFAULT NULL, login_verify_count INTEGER NOT NULL DEFAULT 0, email_new TEXT DEFAULT NULL, email_new_token TEXT DEFAULT NULL, enabled BOOLEAN NOT NULL DEFAULT 1, stamp_exception TEXT DEFAULT NULL, api_key TEXT, avatar_color TEXT, client_kdf_memory INTEGER DEFAULT NULL, client_kdf_parallelism INTEGER DEFAULT NULL, external_id TEXT, key_id TEXT);
CREATE TABLE folders (
  uuid       TEXT     NOT NULL PRIMARY KEY,
  created_at DATETIME NOT NULL,
  updated_at DATETIME NOT NULL,
  user_uuid  TEXT     NOT NULL REFERENCES users (uuid),
  name       TEXT     NOT NULL
);
CREATE TABLE collections (
  uuid     TEXT NOT NULL PRIMARY KEY,
  org_uuid TEXT NOT NULL REFERENCES organizations (uuid),
  name     TEXT NOT NULL
, external_id TEXT);
CREATE TABLE organizations (
  uuid          TEXT NOT NULL PRIMARY KEY,
  name          TEXT NOT NULL,
  billing_email TEXT NOT NULL
, private_key TEXT, public_key TEXT);
CREATE TABLE users_collections (
  user_uuid       TEXT NOT NULL REFERENCES users (uuid),
  collection_uuid TEXT NOT NULL REFERENCES collections (uuid), read_only BOOLEAN NOT NULL DEFAULT 0, hide_passwords BOOLEAN NOT NULL DEFAULT 0, manage BOOLEAN NOT NULL DEFAULT 0,
  PRIMARY KEY (user_uuid, collection_uuid)
);
CREATE TABLE users_organizations (
  uuid       TEXT    NOT NULL PRIMARY KEY,
  user_uuid  TEXT    NOT NULL REFERENCES users (uuid),
  org_uuid   TEXT    NOT NULL REFERENCES organizations (uuid),

  access_all BOOLEAN NOT NULL,
  akey        TEXT    NOT NULL,
  status     INTEGER NOT NULL,
  atype       INTEGER NOT NULL, reset_password_key TEXT, "external_id" TEXT, invited_by_email TEXT DEFAULT NULL, manage_users BOOLEAN NOT NULL DEFAULT 0, manage_groups BOOLEAN NOT NULL DEFAULT 0, manage_policies BOOLEAN NOT NULL DEFAULT 0, create_new_collections BOOLEAN NOT NULL DEFAULT 0, edit_any_collection BOOLEAN NOT NULL DEFAULT 0, delete_any_collection BOOLEAN NOT NULL DEFAULT 0, access_event_logs BOOLEAN NOT NULL DEFAULT 0, access_import_export BOOLEAN NOT NULL DEFAULT 0, access_reports BOOLEAN NOT NULL DEFAULT 0,

  UNIQUE (user_uuid, org_uuid)
);
CREATE TABLE folders_ciphers (
  cipher_uuid TEXT NOT NULL REFERENCES ciphers (uuid),
  folder_uuid TEXT NOT NULL REFERENCES folders (uuid),

  PRIMARY KEY (cipher_uuid, folder_uuid)
);
CREATE TABLE ciphers_collections (
  cipher_uuid       TEXT NOT NULL REFERENCES ciphers (uuid),
  collection_uuid TEXT NOT NULL REFERENCES collections (uuid),
  PRIMARY KEY (cipher_uuid, collection_uuid)
);
CREATE TABLE attachments (
  id          TEXT    NOT NULL PRIMARY KEY,
  cipher_uuid TEXT    NOT NULL REFERENCES ciphers (uuid),
  file_name   TEXT    NOT NULL,
  file_size   INTEGER NOT NULL

, akey TEXT);
CREATE TABLE twofactor (
  uuid      TEXT     NOT NULL PRIMARY KEY,
  user_uuid TEXT     NOT NULL REFERENCES users (uuid),
  atype      INTEGER  NOT NULL,
  enabled   BOOLEAN  NOT NULL,
  data      TEXT     NOT NULL, last_used INTEGER NOT NULL DEFAULT 0,

  UNIQUE (user_uuid, atype)
);
CREATE TABLE invitations (
    email   TEXT NOT NULL PRIMARY KEY
);
CREATE TABLE org_policies (
  uuid      TEXT     NOT NULL PRIMARY KEY,
  org_uuid  TEXT     NOT NULL REFERENCES organizations (uuid),
  atype     INTEGER  NOT NULL,
  enabled   BOOLEAN  NOT NULL,
  data      TEXT     NOT NULL, revision_date DATETIME NOT NULL DEFAULT '1970-01-01 00:00:00',

  UNIQUE (org_uuid, atype)
);
CREATE TABLE favorites (
  user_uuid   TEXT NOT NULL REFERENCES users(uuid),
  cipher_uuid TEXT NOT NULL REFERENCES ciphers(uuid),

  PRIMARY KEY (user_uuid, cipher_uuid)
);
CREATE TABLE "ciphers"(
  uuid              TEXT     NOT NULL PRIMARY KEY,
  created_at        DATETIME NOT NULL,
  updated_at        DATETIME NOT NULL,
  user_uuid         TEXT     REFERENCES users(uuid),
  organization_uuid TEXT     REFERENCES organizations(uuid),
  atype             INTEGER  NOT NULL,
  name              TEXT     NOT NULL,
  notes             TEXT,
  fields            TEXT,
  data              TEXT     NOT NULL,
  password_history  TEXT,
  deleted_at        DATETIME
, reprompt INTEGER, "key" TEXT);
CREATE TABLE sends (
  uuid              TEXT NOT NULL   PRIMARY KEY,
  user_uuid         TEXT            REFERENCES users (uuid),
  organization_uuid TEXT            REFERENCES organizations (uuid),

  name              TEXT    NOT NULL,
  notes             TEXT,

  atype             INTEGER NOT NULL,
  data              TEXT    NOT NULL,
  akey               TEXT    NOT NULL,
  password_hash     BLOB,
  password_salt     BLOB,
  password_iter     INTEGER,

  max_access_count  INTEGER,
  access_count      INTEGER NOT NULL,

  creation_date     DATETIME NOT NULL,
  revision_date     DATETIME NOT NULL,
  expiration_date   DATETIME,
  deletion_date     DATETIME NOT NULL,

  disabled          BOOLEAN NOT NULL
, hide_email BOOLEAN);
CREATE TABLE emergency_access (
  uuid                      TEXT     NOT NULL PRIMARY KEY,
  grantor_uuid              TEXT     REFERENCES users (uuid),
  grantee_uuid              TEXT     REFERENCES users (uuid),
  email                     TEXT,
  key_encrypted             TEXT,
  atype                     INTEGER  NOT NULL,
  status                    INTEGER  NOT NULL,
  wait_time_days            INTEGER  NOT NULL,
  recovery_initiated_at     DATETIME,
  last_notification_at      DATETIME,
  updated_at                DATETIME NOT NULL,
  created_at                DATETIME NOT NULL
);
CREATE TABLE twofactor_incomplete (
  user_uuid   TEXT     NOT NULL REFERENCES users(uuid),
  device_uuid TEXT     NOT NULL,
  device_name TEXT     NOT NULL,
  login_time  DATETIME NOT NULL,
  ip_address  TEXT     NOT NULL, device_type INTEGER NOT NULL DEFAULT 14,

  PRIMARY KEY (user_uuid, device_uuid)
);
CREATE TABLE "devices" (
	uuid	TEXT NOT NULL,
	created_at	DATETIME NOT NULL,
	updated_at	DATETIME NOT NULL,
	user_uuid	TEXT NOT NULL,
	name	TEXT NOT NULL,
	atype	INTEGER NOT NULL,
	push_token	TEXT,
	refresh_token	TEXT NOT NULL,
	twofactor_remember	TEXT, push_uuid TEXT,
	PRIMARY KEY(uuid, user_uuid),
	FOREIGN KEY(user_uuid) REFERENCES users(uuid)
);
CREATE TABLE groups (
  uuid                              TEXT NOT NULL PRIMARY KEY,
  organizations_uuid                TEXT NOT NULL REFERENCES organizations (uuid),
  name                              TEXT NOT NULL,
  access_all                        BOOLEAN NOT NULL,
  external_id                       TEXT NULL,
  creation_date                     TIMESTAMP NOT NULL,
  revision_date                     TIMESTAMP NOT NULL
);
CREATE TABLE groups_users (
  groups_uuid                       TEXT NOT NULL REFERENCES groups (uuid),
  users_organizations_uuid          TEXT NOT NULL REFERENCES users_organizations (uuid),
  UNIQUE (groups_uuid, users_organizations_uuid)
);
CREATE TABLE collections_groups (
  collections_uuid                  TEXT NOT NULL REFERENCES collections (uuid),
  groups_uuid                       TEXT NOT NULL REFERENCES groups (uuid),
  read_only                         BOOLEAN NOT NULL,
  hide_passwords                    BOOLEAN NOT NULL, manage BOOLEAN NOT NULL DEFAULT 0,
  UNIQUE (collections_uuid, groups_uuid)
);
CREATE TABLE event (
  uuid               TEXT        NOT NULL PRIMARY KEY,
  event_type         INTEGER     NOT NULL,
  user_uuid          TEXT,
  org_uuid           TEXT,
  cipher_uuid        TEXT,
  collection_uuid    TEXT,
  group_uuid         TEXT,
  org_user_uuid      TEXT,
  act_user_uuid      TEXT,
  device_type        INTEGER,
  ip_address         TEXT,
  event_date         DATETIME    NOT NULL,
  policy_uuid        TEXT,
  provider_uuid      TEXT,
  provider_user_uuid TEXT,
  provider_org_uuid  TEXT,
  UNIQUE (uuid)
);
CREATE TABLE organization_api_key (
	uuid            TEXT NOT NULL,
    org_uuid	    TEXT NOT NULL,
    atype           INTEGER NOT NULL,
    api_key         TEXT NOT NULL,
	revision_date   DATETIME NOT NULL,
	PRIMARY KEY(uuid, org_uuid),
	FOREIGN KEY(org_uuid) REFERENCES organizations(uuid)
);
CREATE TABLE "auth_requests" (
    uuid                        TEXT NOT NULL PRIMARY KEY,
    user_uuid                   TEXT NOT NULL,
    organization_uuid           TEXT,
    request_device_identifier   TEXT NOT NULL,
    device_type                 INTEGER NOT NULL,
    request_ip                  TEXT NOT NULL,
    response_device_id          TEXT,
    access_code                 TEXT NOT NULL,
    public_key                  TEXT NOT NULL,
    enc_key                     TEXT,
    master_password_hash        TEXT,
    approved                    BOOLEAN,
    creation_date               DATETIME NOT NULL,
    response_date               DATETIME,
    authentication_date         DATETIME,
    FOREIGN KEY (user_uuid) REFERENCES users (uuid),
    FOREIGN KEY (organization_uuid) REFERENCES organizations (uuid)
);
CREATE TABLE sso_users (
  user_uuid           CHAR(36) NOT NULL PRIMARY KEY,
  identifier          TEXT NOT NULL UNIQUE,
  created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(user_uuid) REFERENCES users(uuid) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE twofactor_duo_ctx (
    state      TEXT    NOT NULL,
    user_email TEXT    NOT NULL,
    nonce      TEXT    NOT NULL,
    exp        INTEGER NOT NULL,

    PRIMARY KEY (state)
);
CREATE TABLE sso_auth (
    state               TEXT NOT NULL PRIMARY KEY,
    client_challenge    TEXT NOT NULL,
    nonce               TEXT NOT NULL,
    redirect_uri        TEXT NOT NULL,
    code_response       TEXT,
    auth_response       TEXT,
    created_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
, binding_hash TEXT, code_response_error TEXT);
CREATE TABLE archives (
    user_uuid   CHAR(36) NOT NULL REFERENCES users (uuid) ON DELETE CASCADE,
    cipher_uuid CHAR(36) NOT NULL REFERENCES ciphers (uuid) ON DELETE CASCADE,
    archived_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_uuid, cipher_uuid)
);


-- ===================== Section 2: Workers-only =====================

-- In-flight attachment uploads (moved into `attachments` once the upload completes).
CREATE TABLE IF NOT EXISTS attachments_pending (
  id              TEXT    NOT NULL PRIMARY KEY,
  cipher_id       TEXT    NOT NULL REFERENCES ciphers (uuid),
  file_name       TEXT    NOT NULL,
  file_size       INTEGER NOT NULL,
  akey            TEXT,
  created_at      TEXT    NOT NULL,
  updated_at      TEXT    NOT NULL,
  organization_id TEXT
);
CREATE INDEX IF NOT EXISTS idx_attachments_pending_cipher ON attachments_pending(cipher_id);
CREATE INDEX IF NOT EXISTS idx_attachments_pending_created_at ON attachments_pending(created_at);

-- File Sends whose upload has not completed yet (moved into `sends` on completion).
CREATE TABLE IF NOT EXISTS sends_pending (
  id               TEXT PRIMARY KEY,
  user_id          TEXT NOT NULL,
  name             TEXT NOT NULL,
  notes            TEXT,
  type             INTEGER NOT NULL,
  data             TEXT NOT NULL,
  akey             TEXT NOT NULL,
  password_hash    TEXT, -- hex
  password_salt    TEXT, -- hex
  password_iter    INTEGER,
  max_access_count INTEGER,
  access_count     INTEGER NOT NULL DEFAULT 0,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  expiration_date  TEXT,
  deletion_date    TEXT NOT NULL,
  disabled         INTEGER NOT NULL DEFAULT 0,
  hide_email       INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_sends_pending_user ON sends_pending(user_id);

-- Global equivalent domains dataset (seeded by scripts/seed-global-domains.sh).
CREATE TABLE IF NOT EXISTS global_equivalent_domains (
  type        INTEGER PRIMARY KEY NOT NULL,
  sort_order  INTEGER NOT NULL,
  domains_json TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_global_equivalent_domains_sort_order ON global_equivalent_domains(sort_order);

-- Indexes for the Worker's hot queries (vaultwarden's SQLite schema defines none).
CREATE INDEX IF NOT EXISTS idx_ciphers_user_uuid ON ciphers(user_uuid);
CREATE INDEX IF NOT EXISTS idx_ciphers_org_uuid ON ciphers(organization_uuid);
CREATE INDEX IF NOT EXISTS idx_folders_user_uuid ON folders(user_uuid);
CREATE INDEX IF NOT EXISTS idx_folders_ciphers_folder ON folders_ciphers(folder_uuid);
CREATE INDEX IF NOT EXISTS idx_attachments_cipher_uuid ON attachments(cipher_uuid);
CREATE INDEX IF NOT EXISTS idx_devices_user_uuid ON devices(user_uuid);
CREATE INDEX IF NOT EXISTS idx_devices_refresh_token ON devices(refresh_token);
CREATE INDEX IF NOT EXISTS idx_devices_push_token ON devices(push_token);
CREATE INDEX IF NOT EXISTS idx_auth_requests_user_uuid ON auth_requests(user_uuid);
CREATE INDEX IF NOT EXISTS idx_auth_requests_creation_date ON auth_requests(creation_date);
CREATE INDEX IF NOT EXISTS idx_sends_user_uuid ON sends(user_uuid);
CREATE INDEX IF NOT EXISTS idx_sends_deletion_date ON sends(deletion_date);
CREATE INDEX IF NOT EXISTS idx_twofactor_user_uuid ON twofactor(user_uuid);

-- Read-only views exposing vaultwarden tables in the Worker's model shape (field names the Rust
-- structs deserialize). Reads go through `wk_*`; writes always target the real tables.
-- Per-user state (favorite, folder, archive) is resolved for the cipher's owner (user_uuid);
-- organization ciphers will need a per-user join instead.
CREATE VIEW IF NOT EXISTS wk_ciphers AS
SELECT
  c.uuid AS id,
  c.user_uuid AS user_id,
  c.organization_uuid AS organization_id,
  c.atype AS type,
  -- Rebuild the Worker's single-blob cipher JSON; keys whose column is NULL are omitted
  -- (removing a non-existent path is a no-op).
  json_remove(json_object(
    'name', c.name,
    'notes', c.notes,
    CASE c.atype WHEN 1 THEN 'login' WHEN 2 THEN 'secureNote' WHEN 3 THEN 'card' WHEN 4 THEN 'identity'
      WHEN 5 THEN 'sshKey' WHEN 6 THEN 'bankAccount' WHEN 7 THEN 'driversLicense' WHEN 8 THEN 'passport'
      ELSE 'unknownType' END, json(c.data),
    'fields', json(c.fields),
    'passwordHistory', json(c.password_history),
    'reprompt', c.reprompt,
    'key', c."key"
  ),
    CASE WHEN c.notes IS NULL THEN '$.notes' ELSE '$.-' END,
    CASE WHEN c.data IS NULL OR c.data = 'null' THEN
      '$.' || CASE c.atype WHEN 1 THEN 'login' WHEN 2 THEN 'secureNote' WHEN 3 THEN 'card' WHEN 4 THEN 'identity'
        WHEN 5 THEN 'sshKey' WHEN 6 THEN 'bankAccount' WHEN 7 THEN 'driversLicense' WHEN 8 THEN 'passport'
        ELSE 'unknownType' END
      ELSE '$.-' END,
    CASE WHEN c.fields IS NULL THEN '$.fields' ELSE '$.-' END,
    CASE WHEN c.password_history IS NULL THEN '$.passwordHistory' ELSE '$.-' END,
    CASE WHEN c.reprompt IS NULL THEN '$.reprompt' ELSE '$.-' END,
    CASE WHEN c."key" IS NULL THEN '$.key' ELSE '$.-' END
  ) AS data,
  EXISTS (SELECT 1 FROM favorites f WHERE f.cipher_uuid = c.uuid AND f.user_uuid = c.user_uuid) AS favorite,
  (SELECT fc.folder_uuid FROM folders_ciphers fc JOIN folders fo ON fo.uuid = fc.folder_uuid
     WHERE fc.cipher_uuid = c.uuid AND fo.user_uuid = c.user_uuid LIMIT 1) AS folder_id,
  c.deleted_at,
  (SELECT ar.archived_at FROM archives ar WHERE ar.cipher_uuid = c.uuid AND ar.user_uuid = c.user_uuid) AS archived_at,
  c.created_at,
  c.updated_at
FROM ciphers c;

CREATE VIEW IF NOT EXISTS wk_attachments AS
SELECT a.id, a.cipher_uuid AS cipher_id, a.file_name, a.file_size, a.akey,
       c.created_at, c.updated_at, c.organization_uuid AS organization_id
FROM attachments a JOIN ciphers c ON c.uuid = a.cipher_uuid;

CREATE VIEW IF NOT EXISTS wk_devices AS
SELECT uuid AS identifier, user_uuid AS user_id, name, atype AS type, push_uuid, push_token,
       refresh_token, twofactor_remember, created_at, updated_at
FROM devices;

CREATE VIEW IF NOT EXISTS wk_auth_requests AS
SELECT uuid AS id, user_uuid AS user_id, request_device_identifier, device_type, request_ip,
       response_device_id, access_code, public_key, enc_key, master_password_hash, approved,
       creation_date, response_date, authentication_date
FROM auth_requests;

CREATE VIEW IF NOT EXISTS wk_sends AS
SELECT uuid AS id, user_uuid AS user_id, name, notes, atype AS type, data, akey,
       NULLIF(lower(hex(password_hash)), '') AS password_hash, NULLIF(lower(hex(password_salt)), '') AS password_salt,
       password_iter, max_access_count, access_count, creation_date AS created_at,
       revision_date AS updated_at, expiration_date, deletion_date, disabled,
       COALESCE(hide_email, 0) AS hide_email
FROM sends;
